  @keyframes inFwd{from{transform:translateX(-100%);opacity:.4} to{transform:translateX(0);opacity:1}}
  @keyframes outFwd{from{transform:translateX(0);opacity:1} to{transform:translateX(100%);opacity:.2}}
  @keyframes inBack{from{transform:translateX(100%);opacity:.4} to{transform:translateX(0);opacity:1}}
  @keyframes outBack{from{transform:translateX(0);opacity:1} to{transform:translateX(-100%);opacity:.2}}
  html[dir=ltr] .screen.in-fwd{animation:inFwdL .36s cubic-bezier(.22,.61,.36,1) both}
  html[dir=ltr] .screen.out-fwd{animation:outFwdL .36s cubic-bezier(.22,.61,.36,1) both}
  html[dir=ltr] .screen.in-back{animation:inBackL .36s cubic-bezier(.22,.61,.36,1) both}
  html[dir=ltr] .screen.out-back{animation:outBackL .36s cubic-bezier(.22,.61,.36,1) both}
  @keyframes inFwdL{from{transform:translateX(100%);opacity:.4} to{transform:translateX(0);opacity:1}}
  @keyframes outFwdL{from{transform:translateX(0);opacity:1} to{transform:translateX(-100%);opacity:.2}}
  @keyframes inBackL{from{transform:translateX(-100%);opacity:.4} to{transform:translateX(0);opacity:1}}
  @keyframes outBackL{from{transform:translateX(0);opacity:1} to{transform:translateX(100%);opacity:.2}}

